package com.northstar.crm.ui;import com.northstar.crm.service.AccountService;import com.vaadin.flow.component.UI;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.orderedlayout.VerticalLayout;import com.vaadin.flow.component.textfield.*;import com.vaadin.flow.router.*;import com.vaadin.flow.server.auth.AnonymousAllowed;@Route("accept-invite")@PageTitle("Accept invitation · Northstar")@AnonymousAllowed public class AcceptInviteView extends VerticalLayout implements BeforeEnterObserver {private final AccountService accounts;private String token="";public AcceptInviteView(AccountService a){accounts=a;addClassName("public-form");var name=new TextField("Your name");name.setWidthFull();var password=new PasswordField("Create password");password.setHelperText("12+ characters with upper, lower and number");password.setWidthFull();var card=new VerticalLayout(new H1("Join your customer workspace"),new Paragraph("Set up secure access to shared documents and support requests."),name,password,UiKit.primary("Create account",e->{try{accounts.acceptInvite(token,name.getValue(),password.getValue());UiKit.success("Account created. Sign in to continue.");UI.getCurrent().navigate(LoginView.class);}catch(Exception ex){UiKit.error(ex);}}));card.addClassName("login-card");add(card);setSizeFull();setAlignItems(Alignment.CENTER);setJustifyContentMode(JustifyContentMode.CENTER);}@Override public void beforeEnter(BeforeEnterEvent e){token=e.getLocation().getQueryParameters().getSingleParameter("token").orElse("");}}
